import numpy as np

def step(l,w,s):
    # recurrence monic OP via orthonormal Lanczos
    q=np.ones(len(l)); prev=np.zeros(len(l)); beta=0
    for j in range(s):
        a=np.dot(w,q*q*l)
        z=(l-a)*q-beta*prev
        beta=np.sqrt(np.dot(w,z*z)); prev,q=q,z/beta
    v=w*q*q
    return v/v.sum()
for s in (2,3,4):
 for n in (2*s,2*s+1,2*s+2):
  rng=np.random.default_rng(43)
  l=np.sort(rng.uniform(-1,1,n));w=rng.dirichlet(np.ones(n))
  snaps=[]
  for i in range(20000):
   w=step(l,w,s)
   if i in (999,4999,9999,19999):snaps.append(w.copy())
  print(s,n,l, np.array(snaps),flush=True)

