m,u,v,e=S.symbols('m u v e'); a=S.Rational(1,2);c=(1+a*a)/2;d=(1-a*a)/2
# use polynomial algebra t²=c+dJ and J²=1 for expectation; moments E t=m,E J=u,E tJ=v
T,J=S.symbols('T J')
def E(f):
 f=S.Poly(S.expand(f),T,J);out=0
 for (i,j),coef in f.terms():
  pol=S.Poly(S.expand((c+d*J)**(i//2)*J**j),J)
  for (k,),co in pol.terms():out+=coef*co*([1,u][k%2] if i%2==0 else [m,v][k%2])
 return S.factor(out)
beta=(v-m*u)/(c+d*u-m*m);alpha=u-m*beta
p=J-alpha-beta*T
D=E(p*p)
F=[S.factor(E(t*p*p)/D) for t in (T,J,T*J)]
print('built')
# series around equal weights all small, T²
Fs=[S.series(f.subs({m:e*m,u:e*u,v:e*v}),e,0,4).removeO().expand() for f in F]
F2=[S.series(f.subs({m:Fs[0],u:Fs[1],v:Fs[2]}, simultaneous=True),e,0,4).removeO().expand() for f in F]
for x,f in zip((m,u,v),F2):print(x,S.factor(f-e*x))
